import { G } from '../../../../../core/common/G';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { ICourseCategoryModel, CourseCategoryModel } from '../../../../../data/model/course/CourseCategoryModel';

@Component({
  selector: 'app-edit-category',
  templateUrl: './edit-category.component.html',
  styleUrls: ['./edit-category.component.scss']
})
export class EditCategoryComponent implements OnInit {

  form: FormGroup;
  selectedCategoryModel: ICourseCategoryModel;
  categorySelected = false;
  selectedCategory = 'tuning';
  selectedCategoryId = '0';
  categories$ = G.getCourseCategory();

  constructor(
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private courseService: CourseService
  ) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]],
      url: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]]
    });
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onUpdate(): void {

    if (this.form.valid) {

      SharedIonic.loading(this.loadingController);

      this.courseService.AddOrUpdateCourseCategory(
        new CourseCategoryModel(
          this.selectedCategoryModel.courseCategoryId,
          this.form.value.title,
          this.form.value.url,
          +this.selectedCategoryId || null
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            SharedIonic.successToast(this.toastController);

            this.courseService.GetAllCoursesCategory().subscribe(
              res => {
                if (res.status === GResponse.SuccessStatus) {
                  GResponse.CourseCategory = res.data;
                }
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onCancel(): void {

    this.categorySelected = false;
  }

  onSelectItem(model: ICourseCategoryModel) {

    this.selectedCategoryId = model.parentId == null ? '0' : model.parentId.toString();

    this.selectedCategoryModel = model;

    this.form.setValue({
      title: this.selectedCategoryModel.title,
      url: this.selectedCategoryModel.urlTitle
    });
    this.categorySelected = true;
  }
}

